"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    # Exact match for top-level topics
    if subscribed_pattern == event_topic:
        return True
    # Prefix match for subtopics
    if event_topic.startswith(subscribed_pattern + "::"):
        return True
    # Prefix match for exact topic (no subtopics)
    if event_topic.startswith(subscribed_pattern):
        # Ensure it's not a partial topic match (e.g. "orders" should not match "orders_admin")
        # by checking that the next character after the prefix is either "::" or end of string
        if len(event_topic) == len(subscribed_pattern) or event_topic[len(subscribed_pattern)] == ":":
            return True
    return False

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
